// Strip HTML and extract clean text
const html = $input.first().json.data || $input.first().json.body || '';
const url = $('Webhook').first().json.body.url;

// Basic HTML stripping
let text = html
  // Remove script and style tags entirely
  .replace(/<\s*script[^>]*>[\s\S]*?<\s*\/\s*script\s*>/gi, '')
  .replace(/<\s*style[^>]*>[\s\S]*?<\s*\/\s*style\s*>/gi, '')
  // Remove nav, footer, header elements
  .replace(/<\s*(nav|footer|header|aside)[^>]*>[\s\S]*?<\s*\/\s*(nav|footer|header|aside)\s*>/gi, '')
  // Remove HTML tags
  .replace(/<[^>]+>/g, ' ')
  // Decode common HTML entities
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  // Collapse whitespace
  .replace(/\s+/g, ' ')
  .trim();

// Extract title
const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
const title = titleMatch ? titleMatch[1].trim() : '';

// Detect if content looks empty or JS-rendered (very little text)
const isJSRendered = text.length < 200;

return [{
  json: {
    url,
    raw_text: text,
    title,
    isJSRendered,
    char_count: text.length
  }
}];

